/* ===================== BÀI 16 · Chương trình con và stack ===================== */
/* Bài 16 · Chương trình con và stack (AMTS-EMB-001-M04-L04, MC51-016) — sinh bởi tools/author/mcu8051/l16.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR16=[{"label":"Ví dụ: ACALL, RET và địa chỉ trở về","code":"; Ví dụ 1: ACALL và RET - địa chỉ trở về trên ngăn xếp\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     SP,#5FH                 ; ngăn xếp bắt đầu từ 60H\n        MOV     A,#05H                  ; tham số trong A\n        ACALL   NHAN2                   ; 0005H: gọi, cất 0007H\n        MOV     40H,A                   ; 0007H: trở về đây\n        SJMP    $\nNHAN2:  ADD     A,ACC                   ; A = A + A\n        RET                             ; lấy địa chỉ trở về\n        END\n","note":"Đoán trước: sau ACALL NHAN2 (mã 11 0B, ở 0005H), SP và ô 60H, 61H bằng bao nhiêu? (SP = 61H, ô 60H = 07H byte thấp, ô 61H = 00H byte cao.) RET lấy 0007H ra, SP về 5FH; A = 0AH. Hai ô 60H, 61H vẫn giữ 07H, 00H sau RET.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: PUSH và POP — vào sau, ra trước","code":"; Ví dụ 2: PUSH và POP - vào sau, ra trước\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     A,#11H\n        MOV     B,#22H\n        PUSH    ACC                     ; SP = 60H, ô 60H = 11H\n        PUSH    B                       ; SP = 61H, ô 61H = 22H\n        CLR     A                       ; làm hỏng A, B\n        MOV     B,#00H\n        POP     B                       ; lấy ra theo thứ tự ngược\n        POP     ACC\n        SJMP    $\n        END\n","note":"PUSH ACC rồi PUSH B: ô 60H = 11H, ô 61H = 22H, SP = 61H. POP theo thứ tự ngược (B trước, ACC sau) trả đúng A = 11H, B = 22H. 16 chu kỳ: mỗi PUSH, POP 2 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chương trình con giữ nguyên thanh ghi","code":"; Ví dụ 3: chương trình con giữ nguyên thanh ghi\n; GHI55: ghi 55H vào R3 ô bắt đầu từ ô R1.\n; Giữ nguyên A, R1, R3 cho chương trình gọi.\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     A,#0AAH                 ; A của chương trình chính\n        MOV     R1,#40H                 ; tham số: ô đầu\n        MOV     R3,#3                   ; tham số: số ô\n        LCALL   GHI55\n        MOV     P1,A                    ; A vẫn là AAH?\n        SJMP    $\nGHI55:  PUSH    ACC\n        PUSH    01H                     ; R1 (băng 0) ở ô 01H\n        PUSH    03H                     ; R3 (băng 0) ở ô 03H\n        MOV     A,#55H\nLAP:    MOV     @R1,A\n        INC     R1\n        DJNZ    R3,LAP\n        POP     03H                     ; ngược thứ tự PUSH\n        POP     01H\n        POP     ACC\n        RET\n        END\n","note":"Xem phần Ngăn xếp khi vào GHI55: ô 60H, 61H là địa chỉ trở về 000CH, ô 62H–64H là A, R1, R3 đã cất. Sau RET, A = AAH (P1 = AAH, LED xen kẽ), R1 = 40H, R3 = 03H dù chương trình con đã đổi cả ba; ô 40H–42H = 55H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Gọi lồng nhau và độ sâu ngăn xếp","code":"; Ví dụ 4: gọi lồng nhau - A = 4 x A + 1\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     A,#3\n        ACALL   TINH                    ; mức 1\n        MOV     40H,A\n        SJMP    $\nTINH:   ACALL   NHAN2                   ; mức 2\n        ACALL   NHAN2                   ; mức 2\n        INC     A\n        RET\nNHAN2:  ADD     A,ACC\n        RET\n        END\n","note":"Lời gọi lồng: SP lên tới 63H khi NHAN2 đang chạy. Lần gọi NHAN2 thứ hai ghi đè ô 62H bằng 0FH (địa chỉ trở về mới). Kết quả A = 4 × 3 + 1 = 0DH sau 19 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên đặt SP, ngăn xếp đè băng 1","code":"; Ví dụ 5 (bẫy): quên đặt SP, ngăn xếp đè băng 1\n; Ô 08H, 09H đang chứa hai biến của chương trình.\n        ORG     0000H\n        MOV     08H,#12H                ; biến 1\n        MOV     09H,#34H                ; biến 2\n        ACALL   CON                     ; SP = 07H sau reset!\n        MOV     A,08H                   ; đọc lại biến 1\n        SJMP    $\nCON:    RET\n        END\n","note":"Không có MOV SP: SP = 07H, ACALL cất địa chỉ trở về 0008H vào ô 08H, 09H — đè hai biến 12H, 34H. Cuối cùng A = 08H thay vì 12H. Thêm MOV SP,#5FH ở đầu rồi chạy lại.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: POP cùng thứ tự với PUSH","code":"; Ví dụ 6 (bẫy): POP cùng thứ tự với PUSH\n; XULY muốn giữ nguyên A, B cho chương trình gọi.\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     A,#11H\n        MOV     B,#22H\n        ACALL   XULY\n        MOV     40H,A                   ; mong 11H\n        MOV     41H,B                   ; mong 22H\n        SJMP    $\nXULY:   PUSH    ACC\n        PUSH    B\n        CLR     A                       ; dùng A, B làm việc khác\n        MOV     B,#00H\n        POP     ACC                     ; sai thứ tự!\n        POP     B\n        RET\n        END\n","note":"XULY PUSH ACC rồi PUSH B nhưng POP ACC trước: A nhận 22H (giá trị cất sau cùng), B nhận 11H. Không có lỗi nào được báo, chỉ có 40H = 22H, 41H = 11H sai. Đổi thứ tự hai lệnh POP rồi chạy lại.","dev":{"led":true},"fosc":12000000}];
