makeEx51(document.getElementById("ex-l16"),"l16",[{"t":"Đảo thứ tự 4 byte bằng ngăn xếp","d":"<p>Đảo thứ tự 4 byte ở <code>30H<\/code>–<code>33H<\/code> (30H đổi với 33H, 31H đổi với 32H) bằng các lệnh <code>PUSH<\/code> và <code>POP<\/code>. Băng thanh ghi 1 (ô <code>08H<\/code>–<code>0FH<\/code>) đang chứa biến của chương trình và phải giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H..33H = 11 22 33 44<\/code> → <code>44 33 22 11<\/code>.<\/p>","start":"; Đảo thứ tự 4 byte 30H..33H bằng PUSH và POP:\n; 30H <-> 33H, 31H <-> 32H. Ô 08H..0FH giữ nguyên.\n        ORG     0000H\n; viết chương trình ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":17,"0x31":34,"0x32":51,"0x33":68,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}},"expect":{"iram":{"0x30":68,"0x31":51,"0x32":34,"0x33":17,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":255,"0x33":0,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}},"expect":{"iram":{"0x30":0,"0x31":255,"0x32":0,"0x33":255,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":2,"0x33":1,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":2,"0x33":1,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}}},{"setup":{"iram":{"0x30":165,"0x31":90,"0x32":195,"0x33":60,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}},"expect":{"iram":{"0x30":60,"0x31":195,"0x32":90,"0x33":165,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}}},{"setup":{"iram":{"0x30":128,"0x31":127,"0x32":1,"0x33":254,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}},"expect":{"iram":{"0x30":254,"0x31":1,"0x32":127,"0x33":128,"0x08":176,"0x09":177,"0x0A":178,"0x0B":179,"0x0C":180,"0x0D":181,"0x0E":182,"0x0F":183}}}]},"hints":["Ngăn xếp vào sau ra trước: PUSH lần lượt 30H, 31H, 32H, 33H thì POP đầu tiên lấy ra giá trị cũ của 33H.","PUSH và POP nhận địa chỉ trực tiếp, nên viết thẳng PUSH 30H, POP 30H.","Sau reset SP = 07H: PUSH đầu tiên ghi vào ô 08H, đè lên băng 1. Đặt SP (ví dụ 5FH) trước khi dùng ngăn xếp."],"why":"PUSH bốn ô theo thứ tự rồi POP về bốn ô theo cùng thứ tự địa chỉ thì dữ liệu ra ngược lại. Nếu không đặt SP, ngăn xếp dùng ô 08H–0BH và phá biến ở băng 1 (mọi bộ thử đều kiểm ô 08H–0FH)."},{"t":"Chương trình con giữ nguyên thanh ghi","d":"<p>Chương trình chính truyền tham số qua R0 (địa chỉ đầu, luôn 30H) và R2 (số phần tử n = 1 … 8, đọc từ ô <code>3FH<\/code>) rồi gọi <code>TONG<\/code>. Code mẫu tính đúng <code>40H<\/code> = tổng các phần tử (lấy 8 bit thấp) nhưng làm hỏng A, R0, R2 của chương trình chính. Sửa chương trình con <code>TONG<\/code> để sau khi trở về A, R0, R2 còn nguyên: chương trình chính ghi chúng vào <code>50H<\/code>, <code>51H<\/code>, <code>52H<\/code> và bộ thử kiểm <code>50H = A5H<\/code>, <code>51H = 30H<\/code>, <code>52H<\/code> = n. Không sửa phần chương trình chính.<\/p><p>Ví dụ: <code>3FH = 04H<\/code>, <code>30H..33H = 01 02 03 04<\/code> → <code>40H = 0AH<\/code>.<\/p>","start":"; TONG: 40H = tổng (mod 256) của R2 byte từ ô R0.\n; Chương trình chính cần A, R0, R2 còn nguyên sau khi gọi.\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     R0,#30H                 ; tham số: địa chỉ đầu\n        MOV     R2,3FH                  ; tham số: số phần tử (1..8)\n        MOV     A,#0A5H                 ; A của chương trình chính\n        ACALL   TONG\n        MOV     50H,A                   ; phải còn A5H\n        MOV     51H,R0                  ; phải còn 30H\n        MOV     52H,R2                  ; phải còn số phần tử\n        SJMP    $\nTONG:   CLR     A\nLAP:    ADD     A,@R0\n        INC     R0\n        DJNZ    R2,LAP\n        MOV     40H,A\n        RET\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x3F":4}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x3F":4,"0x40":10,"0x50":165,"0x51":48,"0x52":4}}},{"setup":{"iram":{"0x30":127,"0x3F":1}},"expect":{"iram":{"0x30":127,"0x3F":1,"0x40":127,"0x50":165,"0x51":48,"0x52":1}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x3F":8}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x3F":8,"0x40":248,"0x50":165,"0x51":48,"0x52":8}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x3F":3}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x3F":3,"0x40":0,"0x50":165,"0x51":48,"0x52":3}}},{"setup":{"iram":{"0x30":128,"0x31":128,"0x3F":2}},"expect":{"iram":{"0x30":128,"0x31":128,"0x3F":2,"0x40":0,"0x50":165,"0x51":48,"0x52":2}}},{"setup":{"iram":{"0x30":16,"0x31":32,"0x32":48,"0x33":64,"0x34":80,"0x35":96,"0x36":112,"0x3F":7}},"expect":{"iram":{"0x30":16,"0x31":32,"0x32":48,"0x33":64,"0x34":80,"0x35":96,"0x36":112,"0x3F":7,"0x40":192,"0x50":165,"0x51":48,"0x52":7}}}]},"hints":["Chương trình con dùng A, R0, R2 để tính. Cất chúng lên ngăn xếp ở đầu chương trình con và lấy lại ngay trước RET.","PUSH cần địa chỉ trực tiếp: A là ACC; R0, R2 của băng 0 nằm ở ô 00H, 02H.","Lấy ra theo thứ tự ngược với lúc cất; kết quả phải được ghi trước khi A bị lấy lại."],"why":"Quy ước “chương trình con giữ nguyên thanh ghi nó dùng” giúp chương trình gọi không phải đoán thanh ghi nào bị đổi. Ba cặp PUSH/POP tốn 12 chu kỳ, 12 byte; POP phải ngược thứ tự PUSH, và kết quả phải ghi ra 40H trước khi POP lấy lại A cũ."},{"t":"Rút gọn lời gọi lồng ≤ 14 chu kỳ","d":"<p>Code mẫu tính <code>40H<\/code> = 4 × <code>30H<\/code> (lấy 8 bit thấp) bằng NHAN4 gọi NHAN2 hai lần. Ngăn xếp bắt đầu từ 60H nhưng chỉ được dùng hai ô <code>60H<\/code>, <code>61H<\/code>: ô <code>62H<\/code>, <code>63H<\/code> chứa dữ liệu khác và phải giữ nguyên. Code mẫu đúng kết quả nhưng gọi lồng hai mức (đè 62H, 63H), chạy 20 chu kỳ và dài 22 byte. Viết lại để toàn chương trình chạy không quá <b>14 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>18 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 03H<\/code> → <code>40H = 0CH<\/code>.<\/p>","start":"; 40H = 4 x 30H (mod 256). Ngăn xếp chỉ được dùng\n; ô 60H, 61H. Cần <= 14 chu kỳ, <= 18 byte.\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     A,30H\n        LCALL   NHAN4\n        MOV     40H,A\n        SJMP    $\nNHAN4:  LCALL   NHAN2\n        LCALL   NHAN2\n        RET\nNHAN2:  ADD     A,ACC\n        RET\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x62":165,"0x63":90}},"expect":{"iram":{"0x30":3,"0x62":165,"0x63":90,"0x40":12}}},{"setup":{"iram":{"0x30":0,"0x62":165,"0x63":90}},"expect":{"iram":{"0x30":0,"0x62":165,"0x63":90,"0x40":0}}},{"setup":{"iram":{"0x30":64,"0x62":165,"0x63":90}},"expect":{"iram":{"0x30":64,"0x62":165,"0x63":90,"0x40":0}}},{"setup":{"iram":{"0x30":255,"0x62":165,"0x63":90}},"expect":{"iram":{"0x30":255,"0x62":165,"0x63":90,"0x40":252}}},{"setup":{"iram":{"0x30":63,"0x62":165,"0x63":90}},"expect":{"iram":{"0x30":63,"0x62":165,"0x63":90,"0x40":252}}},{"setup":{"iram":{"0x30":129,"0x62":165,"0x63":90}},"expect":{"iram":{"0x30":129,"0x62":165,"0x63":90,"0x40":4}}}],"maxCyc":14,"maxBytes":18},"hints":["Mỗi mức gọi chiếm 2 ô ngăn xếp. Gọi từ chương trình chính dùng 60H, 61H; NHAN4 gọi tiếp NHAN2 thì dùng 62H, 63H.","Mỗi cặp LCALL + RET tốn 4 chu kỳ và 4 byte. ACALL ngắn hơn LCALL 1 byte, cùng 2 chu kỳ.","NHAN4 có thể làm phép nhân 2 lần thứ nhất rồi “chạy thẳng” xuống NHAN2 nếu NHAN2 đặt ngay sau nó: RET của NHAN2 sẽ trở về chương trình chính."],"why":"Gọi lồng tốn thêm 2 ô ngăn xếp và 4 chu kỳ cho mỗi cặp CALL/RET. Đặt NHAN2 ngay sau NHAN4 để NHAN4 làm một lần nhân rồi rơi xuống NHAN2: chỉ còn một mức gọi (ô 60H, 61H), 12 chu kỳ, 16 byte. Bỏ hẳn lời gọi (tính ngay trong chương trình chính) còn nhanh hơn — cũng là một lời giải đúng."}]);

makeQuiz("quiz16","score16",[{"q": "Ngay sau reset (SP = 07H), lệnh PUSH ACC đầu tiên ghi A vào ô nào?", "o": ["08H — R0 của băng thanh ghi 1", "07H — R7 của băng 0", "60H — vùng ngăn xếp mặc định", "Ô trên cùng FFH của RAM trong"], "a": 0, "e": "PUSH tăng SP trước rồi mới ghi: 07H + 1 = 08H. Ô 08H là R0 của băng 1, nên chương trình cần đặt SP trước khi dùng ngăn xếp."}, {"q": "SP = 5FH. Lệnh ACALL ở địa chỉ 0005H (2 byte) chạy xong. Ngăn xếp thế nào?", "o": ["Ô 60H = 00H, ô 61H = 07H, SP = 61H", "Ô 60H = 05H, ô 61H = 00H, SP = 61H", "Ô 60H = 07H, ô 61H = 00H, SP = 61H", "Ô 5FH = 07H, ô 5EH = 00H, SP = 5DH"], "a": 2, "e": "Địa chỉ trở về là lệnh kế tiếp 0007H. CPU cất byte thấp (07H) trước vào ô 60H, rồi byte cao (00H) vào ô 61H; ngăn xếp lớn lên phía địa chỉ cao."}, {"q": "Muốn cất R0 (đang dùng băng 0) lên ngăn xếp, viết thế nào?", "o": ["PUSH R0", "PUSH @R0", "MOV @SP,R0", "PUSH 00H"], "a": 3, "e": "PUSH chỉ nhận địa chỉ trực tiếp. R0 của băng 0 nằm ở ô 00H. PUSH R0 và PUSH @R0 là lỗi dịch; 8051 không có MOV @SP."}, {"q": "Khác nhau giữa ACALL và LCALL là gì?", "o": ["ACALL 1 chu kỳ, LCALL 2 chu kỳ", "ACALL 2 byte, đích trong cùng trang 2 KB; LCALL 3 byte, đích bất kỳ; cả hai 2 chu kỳ", "ACALL không cất địa chỉ trở về nên kết thúc bằng SJMP", "LCALL cất 3 byte lên ngăn xếp, ACALL cất 2 byte"], "a": 1, "e": "Cả hai đều cất 2 byte địa chỉ trở về và tốn 2 chu kỳ. ACALL mã hóa 11 bit địa chỉ trong 2 byte nên chỉ tới được cùng trang 2 KB; LCALL mang đủ 16 bit."}, {"q": "SP = 5FH. Chương trình chính gọi A, A gọi B, B gọi C; không có PUSH nào. Khi C đang chạy, SP bằng bao nhiêu?", "o": ["65H", "62H", "63H", "5CH"], "a": 0, "e": "Mỗi mức gọi cất 2 byte: 5FH + 3 × 2 = 65H. Ngăn xếp cần ít nhất 6 ô 60H–65H cho đường gọi này (chưa tính ngắt)."}]);

